T=[[0,4,8,6],[4,0,4,3],[8,4,0,5],[6,3,5,0]];wins=[(0,20),(3,10),(5,15),(0,12)];m=pywrapcp.RoutingIndexManager(4,1,0);r=pywrapcp.RoutingModel(m);cb=r.RegisterTransitCallback(lambda a,b:T[m.IndexToNode(a)][m.IndexToNode(b)]);r.SetArcCostEvaluatorOfAllVehicles(cb);r.AddDimension(cb,20,30,False,'Time');d=r.GetDimensionOrDie('Time');[d.CumulVar(m.NodeToIndex(i)).SetRange(*wins[i]) for i in range(1,4)];p=pywrapcp.DefaultRoutingSearchParameters();p.first_solution_strategy=routing_enums_pb2.FirstSolutionStrategy.PATH_CHEAPEST_ARC;print(bool(r.SolveWithParameters(p)))
